360	    /**
361	     * Bootstrap arthas server
362	     *
363	     * @param configure 配置信息
364	     * @throws IOException 服务器启动失败
365	     */
366	    private void bind(Configure configure) throws Throwable {
367	
368	        long start = System.currentTimeMillis();
369	
370	        if (!isBindRef.compareAndSet(false, true)) {
371	            throw new IllegalStateException("already bind");
372	        }
373	
374	        // init random port
375	        if (configure.getTelnetPort() != null && configure.getTelnetPort() == 0) {
376	            int newTelnetPort = SocketUtils.findAvailableTcpPort();
377	            configure.setTelnetPort(newTelnetPort);
378	            logger().info("generate random telnet port: " + newTelnetPort);
379	        }
380	        if (configure.getHttpPort() != null && configure.getHttpPort() == 0) {
381	            int newHttpPort = SocketUtils.findAvailableTcpPort();
382	            configure.setHttpPort(newHttpPort);
383	            logger().info("generate random http port: " + newHttpPort);
384	        }
385	        // try to find appName
386	        if (configure.getAppName() == null) {
387	            configure.setAppName(System.getProperty(ArthasConstants.PROJECT_NAME,
388	                    System.getProperty(ArthasConstants.SPRING_APPLICATION_NAME, null)));
389	        }
390	
391	        try {
392	            if (configure.getTunnelServer() != null) {
393	                tunnelClient = new TunnelClient();
394	                tunnelClient.setAppName(configure.getAppName());
395	                tunnelClient.setId(configure.getAgentId());
396	                tunnelClient.setTunnelServerUrl(configure.getTunnelServer());
397	                tunnelClient.setVersion(ArthasBanner.version());
398	                ChannelFuture channelFuture = tunnelClient.start();
399	                channelFuture.await(10, TimeUnit.SECONDS);
400	            }
401	        } catch (Throwable t) {
402	            logger().error("start tunnel client error", t);
403	        }
404	
405	        try {
406	            ShellServerOptions options = new ShellServerOptions()
407	                            .setInstrumentation(instrumentation)
408	                            .setPid(PidUtils.currentLongPid())
409	                            .setWelcomeMessage(ArthasBanner.welcome());
410	            if (configure.getSessionTimeout() != null) {
411	                options.setSessionTimeout(configure.getSessionTimeout() * 1000);
412	            }
413	
414	            this.httpSessionManager = new HttpSessionManager();
415	            if (IPUtils.isAllZeroIP(configure.getIp()) && StringUtils.isBlank(configure.getPassword())) {
416	                // 当 listen 0.0.0.0 时，强制生成密码，防止被远程连接
417	                String errorMsg = "Listening on 0.0.0.0 is very dangerous! External users can connect to your machine! "
418	                        + "No password is currently configured. " + "Therefore, a default password is generated, "
419	                        + "and clients need to use the password to connect!";
420	                AnsiLog.error(errorMsg);
421	                configure.setPassword(StringUtils.randomString(64));
422	                AnsiLog.error("Generated arthas password: " + configure.getPassword());
423	
424	                logger().error(errorMsg);
425	                logger().info("Generated arthas password: " + configure.getPassword());
426	            }
427	
428	            this.securityAuthenticator = new SecurityAuthenticatorImpl(configure.getUsername(), configure.getPassword());
429	
430	            shellServer = new ShellServerImpl(options);
431	
432	            List<String> disabledCommands = new ArrayList<String>();
433	            if (configure.getDisabledCommands() != null) {
434	                String[] strings = StringUtils.tokenizeToStringArray(configure.getDisabledCommands(), ",");
435	                if (strings != null) {
436	                    disabledCommands.addAll(Arrays.asList(strings));
437	                }
438	            }
439	            BuiltinCommandPack builtinCommands = new BuiltinCommandPack(disabledCommands);
440	            List<CommandResolver> resolvers = new ArrayList<CommandResolver>();
441	            CommandResolver externalCommands = loadExternalCommandResolver(shellServer, builtinCommands);
442	            if (externalCommands != null) {
443	                resolvers.add(externalCommands);
444	            }
445	            resolvers.add(builtinCommands);
446	
447	            //worker group
448	            workerGroup = new NioEventLoopGroup(new DefaultThreadFactory("arthas-TermServer", true));
449	
450	            if (configure.getTelnetPort() != null && configure.getTelnetPort() > 0) {
451	                logger().info("try to bind telnet server, host: {}, port: {}.", configure.getIp(), configure.getTelnetPort());
452	                shellServer.registerTermServer(new HttpTelnetTermServer(configure.getIp(), configure.getTelnetPort(),
453	                        options.getConnectionTimeout(), workerGroup, httpSessionManager));
454	            } else {
455	                logger().info("telnet port is {}, skip bind telnet server.", configure.getTelnetPort());
456	            }
457	            if (configure.getHttpPort() != null && configure.getHttpPort() > 0) {
458	                logger().info("try to bind http server, host: {}, port: {}.", configure.getIp(), configure.getHttpPort());
459	                shellServer.registerTermServer(new HttpTermServer(configure.getIp(), configure.getHttpPort(),
460	                        options.getConnectionTimeout(), workerGroup, httpSessionManager));
461	            } else {
462	                // listen local address in VM communication
463	                if (configure.getTunnelServer() != null) {
464	                    shellServer.registerTermServer(new HttpTermServer(configure.getIp(), configure.getHttpPort(),
465	                            options.getConnectionTimeout(), workerGroup, httpSessionManager));
466	                }
467	                logger().info("http port is {}, skip bind http server.", configure.getHttpPort());
468	            }
469	
470	            for (CommandResolver resolver : resolvers) {
471	                shellServer.registerCommandResolver(resolver);
472	            }
473	
474	            shellServer.listen(new BindHandler(isBindRef));
475	            if (!isBind()) {
476	                throw new IllegalStateException("Arthas failed to bind telnet or http port! Telnet port: "
477	                        + String.valueOf(configure.getTelnetPort()) + ", http port: "
478	                        + String.valueOf(configure.getHttpPort()));
479	            }
480	
481	            //http api session manager
482	            sessionManager = new SessionManagerImpl(options, shellServer.getCommandManager(), shellServer.getJobController());
483	            //http api handler
484	            httpApiHandler = new HttpApiHandler(historyManager, sessionManager);
485	
486	            // Mcp Server
487	            String mcpEndpoint = configure.getMcpEndpoint();
488	            String mcpProtocol = configure.getMcpProtocol();
489	            if (mcpEndpoint != null && !mcpEndpoint.trim().isEmpty()) {
490	                logger().info("try to start mcp server, endpoint: {}, protocol: {}.", mcpEndpoint, mcpProtocol);
491	                CommandExecutor commandExecutor = new CommandExecutorImpl(sessionManager);
492	                this.arthasMcpBootstrap = new ArthasMcpBootstrap(commandExecutor, mcpEndpoint, mcpProtocol);
493	                this.mcpRequestHandler = this.arthasMcpBootstrap.start().getMcpRequestHandler();
494	            }
495	            logger().info("as-server listening on network={};telnet={};http={};timeout={};mcp={};mcpProtocol={};", configure.getIp(),
496	                    configure.getTelnetPort(), configure.getHttpPort(), options.getConnectionTimeout(), configure.getMcpEndpoint(), configure.getMcpProtocol());
497	
498	            // 异步回报启动次数
499	            if (configure.getStatUrl() != null) {
500	                logger().info("arthas stat url: {}", configure.getStatUrl());
501	            }
502	            UserStatUtil.setStatUrl(configure.getStatUrl());
503	            UserStatUtil.setAgentId(configure.getAgentId());
504	            UserStatUtil.arthasStart();
505	
506	            try {
507	                SpyAPI.init();
508	            } catch (Throwable e) {
509	                // ignore
510	            }
511	
512	            logger().info("as-server started in {} ms", System.currentTimeMillis() - start);
513	            logCrossMountNamespaceAttachSuccess(configure, arthasHome(), logger());
514	        } catch (Throwable e) {
515	            logger().error("Error during start as-server", e);
516	            destroy();
517	            throw e;
518	        }
519	    }
