521	    static void logCrossMountNamespaceAttachSuccess(Configure configure, String arthasHome, Logger logger) {
522	        if (!configure.isCrossMountNamespace()) {
523	            return;
524	        }
525	        logger.info("event=arthas_attach status=success mode=cross-mount-namespace "
526	                        + "targetPid={} arthasHome={} network={} telnet={} http={}",
527	                configure.getJavaPid(), arthasHome, configure.getIp(), configure.getTelnetPort(),
528	                configure.getHttpPort());
529	    }
