58	    @Override
59	    public Subject login(Principal principal) throws LoginException {
60	        if (principal == null) {
61	            return null;
62	        }
63	        if (principal instanceof BasicPrincipal) {
64	            BasicPrincipal basicPrincipal = (BasicPrincipal) principal;
65	            if (basicPrincipal.getName().equals(username) && basicPrincipal.getPassword().equals(this.password)) {
66	                return subject;
67	            }
68	        }
69	        if (principal instanceof BearerPrincipal) {
