562	            // load from arthas directory
563	            // 尝试把lib文件复制到临时文件里，避免多次attach时出现 Native Library already loaded in another classloader
564	            FileOutputStream tmpLibOutputStream = null;
565	            FileInputStream libInputStream = null;
566	            try {
567	                File tmpLibFile = File.createTempFile(VmTool.JNI_LIBRARY_NAME, null);
568	                tmpLibOutputStream = new FileOutputStream(tmpLibFile);
569	                libInputStream = new FileInputStream(libPath);
570	
571	                IOUtils.copy(libInputStream, tmpLibOutputStream);
572	                libPath = tmpLibFile.getAbsolutePath();
573	                logger.debug("copy {} to {}", libPath, tmpLibFile);
574	            } catch (Throwable e) {
575	                logger.error("try to copy lib error! libPath: {}", libPath, e);
576	            } finally {
577	                IOUtils.close(libInputStream);
578	                IOUtils.close(tmpLibOutputStream);
579	            }
580	            profiler = AsyncProfiler.getInstance(libPath);
581	        } else {
582	            if (OSUtils.isLinux() || OSUtils.isMac()) {
583	                throw new IllegalStateException("Can not find libasyncProfiler so, please check the arthas directory.");
584	            } else {
585	                throw new IllegalStateException("Current OS do not support AsyncProfiler, Only support Linux/Mac.");
586	            }
587	        }
588	
589	        return profiler;
590	    }
