606	    private String executeArgs(ProfilerAction action) {
607	        StringBuilder sb = new StringBuilder();
608	
609	        sb.append(action).append(',');
610	
611	        appendParam(sb, "event", this.event);
612	        appendParam(sb, "alloc", this.alloc);
613	        appendFlag(sb, "live", this.live);
614	        appendParam(sb, "lock", this.lock);
615	        if (this.jfrsync != null) {
