621	        boolean passFile = this.file != null;
622	        if (markdown && (action == ProfilerAction.start || action == ProfilerAction.resume)) {
623	            passFile = false;
624	        }
625	        if (passFile) {
626	            sb.append("file=").append(this.file).append(',');
627	        }
628	        if (this.format != null && !markdown) {
629	            sb.append(this.format).append(',');
630	        }
631	        appendParam(sb, "interval", this.interval);
632	        appendParam(sb, "features", this.features);
633	        appendParam(sb, "signal", this.signal);
634	        appendParam(sb, "clock", this.clock);
635	        appendParam(sb, "jstackdepth", this.jstackdepth);
636	        appendFlag(sb, "threads", this.threads);
637	        appendFlag(sb, "sched", this.sched);
638	        appendParam(sb, "cstack", this.cstack);
639	        appendFlag(sb, "simple", this.simple);
640	        appendFlag(sb, "sig", this.sig);
641	        appendFlag(sb, "ann", this.ann);
642	        appendFlag(sb, "lib", this.lib);
643	        appendFlag(sb, "alluser", this.alluser);
644	        appendFlag(sb, "norm", this.norm);
645	        if (this.includes != null) {
646	            for (String include : includes) {
647	                sb.append("include=").append(include).append(',');
648	            }
649	        }
650	        if (this.excludes != null) {
651	            for (String exclude : excludes) {
652	                sb.append("exclude=").append(exclude).append(',');
653	            }
654	        }
655	        if (this.ttsp) {
656	            this.begin = "SafepointSynchronize::begin";
657	            this.end = "RuntimeService::record_safepoint_synchronized";
658	        }
659	        appendParam(sb, "begin", this.begin);
