686	    private static String execute(AsyncProfiler asyncProfiler, String arg)
687	            throws IllegalArgumentException, IOException {
688	        logger.info("profiler execute args: {}", arg);
689	        String result = asyncProfiler.execute(arg);
690	        if (!result.endsWith("\n")) {
691	            result += "\n";
692	        }
