696	    @Override
697	    public void process(final CommandProcess process) {
698	        try {
699	            ProfilerAction profilerAction = ProfilerAction.valueOf(action);
700	
701	            if (ProfilerAction.actions.equals(profilerAction)) {
702	                process.appendResult(new ProfilerModel(actions()));
703	                process.end();
704	                return;
705	            }
706	
707	            final AsyncProfiler asyncProfiler = this.profilerInstance();
708	
709	            if (ProfilerAction.execute.equals(profilerAction)) {
710	                if (actionArg == null) {
711	                    process.end(1, "actionArg can not be empty.");
712	                    return;
713	                }
714	                String result = execute(asyncProfiler, this.actionArg);
715	                appendExecuteResult(process, result);
716	            } else if (ProfilerAction.start.equals(profilerAction)) {
717	                handleStart(process, asyncProfiler);
718	            } else if (ProfilerAction.stop.equals(profilerAction) || ProfilerAction.dump.equals(profilerAction)) {
719	                ProfilerModel profilerModel = processStop(asyncProfiler, profilerAction);
720	                process.appendResult(profilerModel);
721	            } else if (ProfilerAction.resume.equals(profilerAction)) {
722	                String executeArgs = executeArgs(ProfilerAction.resume);
723	                String result = execute(asyncProfiler, executeArgs);
724	                appendExecuteResult(process, result);
725	            } else if (ProfilerAction.version.equals(profilerAction)) {
726	                String result = asyncProfiler.execute("version=full");
727	                appendExecuteResult(process, result);
728	            } else if (ProfilerAction.status.equals(profilerAction)
729	                    || ProfilerAction.meminfo.equals(profilerAction)
730	                    || ProfilerAction.list.equals(profilerAction)) {
731	                String result = asyncProfiler.execute(profilerAction.toString());
732	                appendExecuteResult(process, result);
733	            } else if (ProfilerAction.dumpCollapsed.equals(profilerAction)) {
734	                if (actionArg == null) {
735	                    actionArg = "TOTAL";
736	                }
737	                actionArg = actionArg.toUpperCase();
738	                if ("TOTAL".equals(actionArg) || "SAMPLES".equals(actionArg)) {
739	                    String result = asyncProfiler.dumpCollapsed(Counter.valueOf(actionArg));
740	                    appendExecuteResult(process, result);
741	                } else {
742	                    process.end(1, "ERROR: dumpCollapsed argumment should be TOTAL or SAMPLES. ");
743	                    return;
744	                }
745	            } else if (ProfilerAction.dumpFlat.equals(profilerAction)) {
746	                int maxMethods = 0;
747	                if (actionArg != null) {
748	                    maxMethods = Integer.valueOf(actionArg);
749	                }
750	                String result = asyncProfiler.dumpFlat(maxMethods);
751	                appendExecuteResult(process, result);
752	            } else if (ProfilerAction.dumpTraces.equals(profilerAction)) {
753	                int maxTraces = 0;
754	                if (actionArg != null) {
755	                    maxTraces = Integer.valueOf(actionArg);
756	                }
757	                String result = asyncProfiler.dumpTraces(maxTraces);
758	                appendExecuteResult(process, result);
759	            } else if (ProfilerAction.getSamples.equals(profilerAction)) {
760	                String result = "" + asyncProfiler.getSamples() + "\n";
761	                appendExecuteResult(process, result);
762	            }
763	            process.end();
764	        } catch (Throwable e) {
765	            logger.error("AsyncProfiler error", e);
766	            process.end(1, "AsyncProfiler error: "+e.getMessage());
767	        }
768	    }
