770	    private void handleStart(CommandProcess process, final AsyncProfiler asyncProfiler) throws IOException {
771	        boolean autoGeneratedFile = false;
772	        if (this.file != null) {
773	            fileSpecifiedAtStart = this.file;
774	            logger.debug("File specified during profiler start: {}", fileSpecifiedAtStart);
775	        } else if (this.timeout != null) {
776	            try {
777	                this.file = outputFile();
778	                logger.debug("Auto-generated file for timeout: {}", this.file);
779	                fileSpecifiedAtStart = this.file;
780	                autoGeneratedFile = true;
781	            } catch (IOException e) {
782	                logger.warn("Failed to auto-generate file for timeout", e);
783	            }
784	        }
785	
786	        if (this.duration == null) {
787	            String executeArgs = executeArgs(ProfilerAction.start);
788	            String result = execute(asyncProfiler, executeArgs);
789	            ProfilerModel profilerModel = createProfilerModel(result);
790	            if (autoGeneratedFile && this.file != null) {
791	                profilerModel.setOutputFile(this.file);
792	                profilerModel.setExecuteResult(profilerModel.getExecuteResult()
793	                        + "\nAuto-generated output file will be: " + this.file + "\n");
794	            }
795	            process.appendResult(profilerModel);
796	        } else {
797	            // 设置延时执行 stop
798	            final String outputFile = outputFile();
799	            String executeArgs = executeArgs(ProfilerAction.start);
800	            String result = execute(asyncProfiler, executeArgs);
801	            ProfilerModel profilerModel = createProfilerModel(result);
802	            profilerModel.setOutputFile(outputFile);
803	            profilerModel.setDuration(duration);
804	            ArthasBootstrap.getInstance().getScheduledExecutorService().schedule(new Runnable() {
805	                @Override
806	                public void run() {
807	                    // 在异步线程执行，profiler命令已经结束，不能输出到客户端
808	                    try {
809	                        logger.info("stopping profiler ...");
810	                        ProfilerModel model = processStop(asyncProfiler, ProfilerAction.stop);
811	                        logger.info("profiler output file: " + model.getOutputFile());
812	                        logger.info("stop profiler successfully.");
813	                    } catch (Throwable e) {
814	                        logger.error("stop profiler failure", e);
815	                    }
816	                }
817	            }, this.duration, TimeUnit.SECONDS);
818	            process.appendResult(profilerModel);
819	        }
820	    }
821	
822	    private ProfilerModel processStop(AsyncProfiler asyncProfiler, ProfilerAction profilerAction) throws IOException {
823	        // profiler stop --file xxx.md：自动推断为 Markdown 输出
824	        if (this.format == null && this.file != null && this.file.toLowerCase().endsWith(".md")) {
825	            this.format = "md";
826	        }
827	
828	        if (isMarkdownFormat() && (profilerAction == ProfilerAction.stop || profilerAction == ProfilerAction.dump)) {
829	            return processStopMarkdown(asyncProfiler, profilerAction);
830	        }
831	
832	        String outputFile = null;
833	
834	        // If we're stopping and a file was specified during start, don't generate a new
835	        // output file
836	        if (profilerAction == ProfilerAction.stop && fileSpecifiedAtStart != null) {
837	            outputFile = fileSpecifiedAtStart;
838	            // Reset the tracking variable after stop
839	            logger.debug("Using file specified during start: {}", fileSpecifiedAtStart);
840	            fileSpecifiedAtStart = null;
841	        } else {
842	            // Otherwise generate or use the specified output file
843	            outputFile = outputFile();
844	        }
845	
846	        String executeArgs = executeArgs(profilerAction);
847	        String result = execute(asyncProfiler, executeArgs);
848	
849	        ProfilerModel profilerModel = createProfilerModel(result);
850	        if (outputFile != null) {
851	            profilerModel.setOutputFile(outputFile);
852	        }
853	        return profilerModel;
854	    }
855	
856	    private ProfilerModel processStopMarkdown(AsyncProfiler asyncProfiler, ProfilerAction profilerAction) throws IOException {
857	        // Markdown 输出：先让 async-profiler 输出 collapsed 文本，再在 Arthas 侧做结构化汇总。
858	        String userFormat = this.format;
859	        String userFile = this.file;
860	        int topN = mdTopN(userFormat);
861	
862	        // stop 时如果 start 阶段指定过 file，需要清理掉，避免影响后续 stop 行为
863	        if (profilerAction == ProfilerAction.stop) {
864	            fileSpecifiedAtStart = null;
865	        }
866	
867	        File collapsedFile = File.createTempFile("arthas-profiler-collapsed", ".txt");
868	        String collapsed;
869	        try {
870	            // 为避免 async-profiler 由于历史 file 配置导致返回 OK 而非 collapsed 文本，这里强制输出到临时文件后再读取。
871	            this.file = collapsedFile.getAbsolutePath();
872	            this.format = "collapsed";
873	
874	            String executeArgs = executeArgs(profilerAction);
875	            execute(asyncProfiler, executeArgs);
876	
877	            collapsed = FileUtils.readFileToString(collapsedFile, StandardCharsets.UTF_8);
878	        } finally {
879	            // best-effort cleanup
880	            try {
881	                collapsedFile.delete();
882	            } catch (Throwable ignore) {
883	                // ignore
884	            }
885	            this.format = userFormat;
886	            this.file = userFile;
887	        }
888	
889	        String markdown = ProfilerMarkdown.toMarkdown(new ProfilerMarkdown.Options()
890	                .action(profilerAction.name())
891	                .event(this.event)
892	                .threads(this.threads)
893	                .topN(topN)
894	                .collapsed(collapsed));
895	
896	        String outputFile = null;
897	        if (userFile != null && !userFile.trim().isEmpty()) {
898	            outputFile = userFile;
899	            FileUtils.writeByteArrayToFile(new File(outputFile), markdown.getBytes(StandardCharsets.UTF_8));
900	        }
901	
902	        ProfilerModel profilerModel = createProfilerModel(markdown);
903	        profilerModel.setFormat(userFormat);
904	        profilerModel.setOutputFile(outputFile);
905	        return profilerModel;
906	    }
907	
908	    private int mdTopN(String format) {
909	        final int defaultTopN = 10;
910	        if (format == null) {
911	            return defaultTopN;
912	        }
913	        String f = format.trim().toLowerCase();
914	        if (!f.startsWith("md")) {
915	            return defaultTopN;
916	        }
917	        int idx = f.indexOf('=');
918	        if (idx < 0 || idx == f.length() - 1) {
919	            return defaultTopN;
920	        }
921	        try {
922	            int n = Integer.parseInt(f.substring(idx + 1).trim());
923	            return n > 0 ? n : defaultTopN;
924	        } catch (Throwable e) {
925	            return defaultTopN;
926	        }
927	    }
928	
929	    private String outputFile() throws IOException {
930	        if (this.file == null) {
931	            String fileExt = outputFileExt();
932	            File outputPath = ArthasBootstrap.getInstance().getOutputPath();
933	            if (outputPath != null) {
934	                this.file = new File(outputPath,
935	                        new SimpleDateFormat("yyyyMMdd-HHmmss").format(new Date()) + "." + fileExt)
936	                                .getAbsolutePath();
937	            } else {
938	                this.file = File.createTempFile("arthas-output", "." + fileExt).getAbsolutePath();
939	            }
940	        }
941	        return file;
942	    }
943	
944	    /**
945	     * This method should only be called when {@code this.file == null} is true.
946	     */
947	    private String outputFileExt() {
948	        String fileExt = "";
949	        if (this.format == null) {
950	            fileExt = "html";
951	        } else if (this.format.toLowerCase().startsWith("md")) {
952	            fileExt = "md";
953	        } else if (this.format.startsWith("flat") || this.format.startsWith("traces") 
954	                || this.format.equals("collapsed")) {
955	            fileExt = "txt";
956	        } else if (this.format.equals("flamegraph") || this.format.equals("tree")) {
957	            fileExt = "html";
958	        } else if (this.format.equals("jfr")) {
959	            fileExt = "jfr";
960	        } else {
961	            // illegal -o option makes async-profiler use flat
962	            fileExt = "txt";
963	        }
964	        return fileExt;
965	    }
966	
967	    private void appendExecuteResult(CommandProcess process, String result) {
968	        ProfilerModel profilerModel = createProfilerModel(result);
969	        process.appendResult(profilerModel);
970	    }
971	
972	    private ProfilerModel createProfilerModel(String result) {
973	        ProfilerModel profilerModel = new ProfilerModel();
974	        profilerModel.setAction(action);
975	        profilerModel.setActionArg(actionArg);
976	        profilerModel.setFormat(format);
977	        profilerModel.setExecuteResult(result);
978	        return profilerModel;
979	    }
