981	    private List<String> events() {
982	        List<String> result = new ArrayList<String>();
983	
984	        String execute;
985	        try {
986	            /**
987	             * <pre>
988	               Basic events:
989	                  cpu
990	                  alloc
991	                  lock
992	                  wall
993	                  itimer
994	             * </pre>
995	             */
996	            execute = this.profilerInstance().execute("list");
997	        } catch (Throwable e) {
998	            // ignore
999	            return result;
1000	        }
1001	        String lines[] = execute.split("\\r?\\n");
1002	
1003	        for (String line : lines) {
1004	            if (line.startsWith(" ")) {
1005	                result.add(line.trim());
1006	            }
1007	        }
1008	        return result;
