1019	    @Override
1020	    public void complete(Completion completion) {
1021	        List<CliToken> tokens = completion.lineTokens();
1022	        String token = tokens.get(tokens.size() - 1).value();
1023	
1024	        if (tokens.size() >= 2) {
1025	            CliToken cliToken_1 = tokens.get(tokens.size() - 1);
1026	            CliToken cliToken_2 = tokens.get(tokens.size() - 2);
1027	            if (cliToken_1.isBlank()) {
1028	                String token_2 = cliToken_2.value();
1029	                if (token_2.equals("-e") || token_2.equals("--event")) {
1030	                    CompletionUtils.complete(completion, events());
1031	                    return;
1032	                } else if (token_2.equals("-o") || token_2.equals("--format")) {
1033	                    CompletionUtils.complete(completion, Arrays.asList(
1034	                            "flamegraph", "tree", "jfr",
1035	                            "flat", "traces", "collapsed",
1036	                            "md", "md=10"
1037	                    ));
1038	                    return;
1039	                }
1040	            }
1041	        }
1042	
1043	        if (token.startsWith("-")) {
1044	            super.complete(completion);
1045	            return;
1046	        }
1047	
1048	        CompletionUtils.complete(completion, actions());
1049	    }
1050	
