    // Track if a file was specified during profiler start (instance field: each command invocation is independent)
    private String fileSpecifiedAtStart = null;

    // TODO start 时，没指定 file， 是否在  stop 时，能生成 html 或者 jfr 不？ 
    private String action;
    private String actionArg;

